//! secrets-anything: Find leaked API keys, tokens, passwords and private keys in any codebase, in any language, before you push. Fast, offline, no false alarms on test fixtures.
//!
//! Generated by anything-anything from anything.toml: change that file and run `anything-anything sync`.
//! Your code lives in src/commands/ (one file per command) and src/engine/.

mod commands;
mod engine;
mod mcp;
mod ui;

use clap::{Parser, Subcommand};
use std::process::ExitCode;

#[derive(Parser)]
#[command(
    name = "secrets-anything",
    version,
    about = "Find leaked API keys, tokens, passwords and private keys in any codebase, in any language, before you push. Fast, offline, no false alarms on test fixtures.",
    arg_required_else_help = true
)]
struct Cli {
    /// Print the result as JSON
    #[arg(long, global = true)]
    json: bool,
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// Find leaked secrets in a folder or file
    #[command(name = "scan")]
    Scan(commands::args::ScanArgs),
    /// Find leaked secrets in text from stdin
    #[command(name = "check")]
    Check(commands::args::CheckArgs),
    /// List the built-in detection rules
    #[command(name = "rules")]
    Rules(commands::args::RulesArgs),
    /// Run as an MCP server on stdio (Claude Code, Codex, Cursor, ...)
    Mcp,
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    let result = match cli.cmd {
        Cmd::Scan(args) => commands::scan::run(&args),
        Cmd::Check(args) => commands::check::run(&args),
        Cmd::Rules(args) => commands::rules::run(&args),
        Cmd::Mcp => mcp::serve().map(|()| commands::Output::default()),
    };
    match result {
        Ok(out) => {
            out.print(cli.json);
            ExitCode::from(out.exit)
        }
        Err(e) => {
            ui::error(format!("{e:#}"));
            ExitCode::FAILURE
        }
    }
}
